import { Controller, HttpCode, Patch, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 차트 유형은 API 명세의 허용 값이다.
const CHART_TYPES = ['막대형', '선형', '원형'];
// 가정: 신규 저장 시 ECM 연계 전이므로 '대기'로 시작한다.
const ECM_SYNC_INITIAL = '대기';
// 가정: 변환을 지원하는 원본 파일 형식은 HWP·Word 계열이다.
const SOURCE_EXTENSIONS = ['hwp', 'hwpx', 'doc', 'docx'];

function isPresent(value: unknown): boolean {
  return value !== undefined && value !== null;
}

function textOf(value: unknown, label: string, max: number): string {
  if (typeof value !== 'string') {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  if (value.length > max) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '은(는) ' + max + '자 이하로 입력해 주세요.');
  }
  return value;
}

function titleOf(value: unknown): string {
  const title = textOf(value, '문서 제목', 300);
  if (title.trim() === '') {
    throw new ApiError(400, 'VALIDATION_FAILED', '문서 제목을 입력해 주세요.');
  }
  return title;
}

function checkChart(type: unknown, chartData: unknown): void {
  if (typeof type !== 'string' || !CHART_TYPES.includes(type)) {
    throw new ApiError(422, 'INVALID_CHART_DATA', '차트 유형은 막대형, 선형, 원형 중에서 선택해 주세요.');
  }
  if (typeof chartData !== 'object' || chartData === null || Array.isArray(chartData)) {
    throw new ApiError(422, 'INVALID_CHART_DATA', '차트 데이터가 없거나 형식이 올바르지 않습니다.');
  }
}

function checkSourceFile(name: string): void {
  const dot = name.lastIndexOf('.');
  const ext = dot < 0 ? '' : name.slice(dot + 1).toLowerCase();
  if (!SOURCE_EXTENSIONS.includes(ext)) {
    throw new ApiError(422, 'UNSUPPORTED_SOURCE_FILE', '지원하지 않는 변환 파일 형식입니다. HWP 또는 Word 파일만 변환할 수 있습니다.');
  }
}

@Controller('api/v1')
export class FnSfr04101Controller {
  @Post('/office-documents')
  @HttpCode(200)
  async createOfficeDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);

    const title = titleOf(data['title']);
    const content = isPresent(data['content']) ? textOf(data['content'], '문서 본문', 10000000) : null;
    const templateName = isPresent(data['templateName']) ? textOf(data['templateName'], '문서 템플릿', 100) : null;
    const sourceFileName = isPresent(data['sourceFileName']) ? textOf(data['sourceFileName'], '변환 원본 파일명', 255) : null;
    if (sourceFileName !== null) {
      checkSourceFile(sourceFileName);
    }

    const chartType = isPresent(data['chartType']) ? data['chartType'] : null;
    const chartData = isPresent(data['chartData']) ? data['chartData'] : null;
    if (chartType !== null || chartData !== null) {
      checkChart(chartType, chartData);
    }

    return transaction(async (db) => {
      const rows = await db.query(
        `INSERT INTO office_document
           (author_id, title, content, template_name, source_file_name,
            chart_type, chart_data, ecm_sync_status, created_at, updated_at)
         VALUES
           (CAST(:userId AS bigint), :title, :content, :templateName, :sourceFileName,
            :chartType, CAST(:chartData AS jsonb), :ecmSyncStatus, now(), now())
         RETURNING office_document_id AS "officeDocumentId",
                   title AS "title",
                   content AS "content",
                   chart_type AS "chartType",
                   chart_data AS "chartData"`,
        {
          userId: user.id,
          title,
          content,
          templateName,
          sourceFileName,
          chartType,
          chartData: chartData === null ? null : JSON.stringify(chartData),
          ecmSyncStatus: ECM_SYNC_INITIAL,
        },
      );
      return rows[0];
    });
  }

  @Patch('/office-documents/:officeDocumentId')
  async updateOfficeDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const officeDocumentId = req.params['officeDocumentId'];
    if (!/^[0-9]+$/.test(officeDocumentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 ID가 올바르지 않습니다.');
    }

    const title = isPresent(data['title']) ? titleOf(data['title']) : null;
    const content = isPresent(data['content']) ? textOf(data['content'], '문서 본문', 10000000) : null;
    const chartTypeIn = isPresent(data['chartType']) ? data['chartType'] : null;
    const chartDataIn = isPresent(data['chartData']) ? data['chartData'] : null;

    return transaction(async (db) => {
      const found = await db.query(
        `SELECT chart_type AS "chartType", chart_data AS "chartData"
           FROM office_document
          WHERE office_document_id = CAST(:id AS bigint)`,
        { id: officeDocumentId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'OFFICE_DOCUMENT_NOT_FOUND', '문서를 찾을 수 없습니다.');
      }
      if (chartTypeIn !== null || chartDataIn !== null) {
        const effectiveType = chartTypeIn !== null ? chartTypeIn : found[0]['chartType'];
        const effectiveData = chartDataIn !== null ? chartDataIn : found[0]['chartData'];
        checkChart(effectiveType, effectiveData);
      }

      const rows = await db.query(
        `UPDATE office_document
            SET title = COALESCE(CAST(:title AS varchar), title),
                content = COALESCE(CAST(:content AS text), content),
                chart_type = COALESCE(CAST(:chartType AS varchar), chart_type),
                chart_data = COALESCE(CAST(:chartData AS jsonb), chart_data),
                updated_at = now()
          WHERE office_document_id = CAST(:id AS bigint)
          RETURNING office_document_id AS "officeDocumentId",
                    title AS "title",
                    content AS "content"`,
        {
          id: officeDocumentId,
          title,
          content,
          chartType: chartTypeIn,
          chartData: chartDataIn === null ? null : JSON.stringify(chartDataIn),
        },
      );
      return rows[0];
    });
  }
}

