import { useState } from 'react';
import {
  call,
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  Select,
  TextInput,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

const CHART_OPTIONS: [string, string][] = [
  ['막대형', '막대형'],
  ['선형', '선형'],
  ['원형', '원형'],
];

// 「라벨,값」 형식으로 한 줄씩 적은 글을 차트 데이터 객체로 바꾼다.
function parseChart(text: string): Row {
  const labels: string[] = [];
  const values: number[] = [];
  const lines = text.split('\n');
  for (const line of lines) {
    if (line.trim() === '') {
      continue;
    }
    const parts = line.split(',');
    const value = Number(parts[1]);
    if (parts.length !== 2 || parts[0].trim() === '' || parts[1].trim() === '' || Number.isNaN(value)) {
      throw new Error('차트 데이터는 「라벨,값」 형식으로 한 줄씩 입력해 주세요.');
    }
    labels.push(parts[0].trim());
    values.push(value);
  }
  if (labels.length === 0) {
    throw new Error('차트 데이터를 입력해 주세요.');
  }
  return { labels, values };
}

export default function FnSfr04101Page({ role, notify }: PageProps) {
  const [docs, setDocs] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [templateName, setTemplateName] = useState('');
  const [sourceFileName, setSourceFileName] = useState('');
  const [chartType, setChartType] = useState('');
  const [chartText, setChartText] = useState('');

  function openCreate() {
    setTitle('');
    setContent('');
    setTemplateName('');
    setSourceFileName('');
    setChartType('');
    setChartText('');
    setCreating(true);
  }

  function openEdit(row: Row) {
    setTitle(String(row['title'] ?? ''));
    setContent(String(row['content'] ?? ''));
    setChartType(String(row['chartType'] ?? ''));
    setChartText(String(row['chartText'] ?? ''));
    setEditing(row);
  }

  function chartOf(): Row | undefined {
    if (chartType === '' && chartText.trim() === '') {
      return undefined;
    }
    if (chartType === '') {
      throw new Error('차트 유형을 선택해 주세요.');
    }
    return parseChart(chartText);
  }

  async function create() {
    if (title.trim() === '') {
      throw new Error('문서 제목을 입력해 주세요.');
    }
    const chartData = chartOf();
    const body: Row = { title, content, templateName, sourceFileName };
    if (chartData) {
      body.chartType = chartType;
      body.chartData = chartData;
    }
    const saved = await call('POST', '/office-documents', role, body);
    setDocs([{ ...saved, chartText }, ...docs]);
    setCreating(false);
    notify('문서를 저장했습니다.');
  }

  async function update() {
    if (!editing) {
      return;
    }
    if (title.trim() === '') {
      throw new Error('문서 제목을 입력해 주세요.');
    }
    const chartData = chartOf();
    const body: Row = { title, content };
    if (chartData) {
      body.chartType = chartType;
      body.chartData = chartData;
    }
    const saved = await call('PATCH', '/office-documents/' + String(editing['officeDocumentId']), role, body);
    setDocs(
      docs.map((d) =>
        d['officeDocumentId'] === editing['officeDocumentId']
          ? { ...d, ...saved, chartType: chartData ? chartType : d['chartType'], chartText }
          : d,
      ),
    );
    setEditing(null);
    notify('문서를 수정했습니다.');
  }

  const chartFields = (
    <>
      <Field label='차트 유형'>
        <Select value={chartType} onChange={setChartType} options={CHART_OPTIONS} placeholder='차트 없음' />
      </Field>
      <Field label='차트 데이터' wide hint='한 줄에 하나씩 「라벨,값」 형식으로 입력'>
        <TextInput value={chartText} onChange={setChartText} multiline placeholder={'1분기,120\n2분기,150'} />
      </Field>
    </>
  );

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>이번 작업 저장</h2>
        <Tiles items={[['저장한 문서', docs.length]]} />
      </section>
      <section className='box span-8'>
        <h2>저장한 문서</h2>
        <Band total={docs.length}>
          <button type='button' className='btn' onClick={openCreate}>새 문서 작성</button>
        </Band>
        <DataTable
          rows={docs}
          empty='저장한 문서가 없습니다.'
          columns={[
            { key: 'title', label: '문서 제목' },
            { key: 'chartType', label: '차트 유형', render: (r) => (r['chartType'] ? <Badge value={r['chartType']} /> : <span>-</span>) },
            {
              key: 'edit',
              label: '편집',
              render: (r) => (
                <button type='button' className='btn' onClick={() => openEdit(r)}>수정</button>
              ),
            },
          ]}
        />
      </section>
      {creating && (
        <Drawer title='새 문서 작성' onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit='저장'>
            <Field label='문서 제목' required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label='문서 템플릿'>
              <TextInput value={templateName} onChange={setTemplateName} placeholder='예: 보고서' />
            </Field>
            <Field label='변환 원본 파일명' hint='HWP·Word 변환 시에만 입력'>
              <TextInput value={sourceFileName} onChange={setSourceFileName} placeholder='예: 기획서.docx' />
            </Field>
            <Field label='문서 본문' wide>
              <TextInput value={content} onChange={setContent} multiline />
            </Field>
            {chartFields}
          </Form>
        </Drawer>
      )}
      {editing && (
        <Drawer title='문서 편집' onClose={() => setEditing(null)}>
          <Form onSubmit={update} submit='저장'>
            <Field label='문서 제목' required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label='문서 본문' wide>
              <TextInput value={content} onChange={setContent} multiline />
            </Field>
            {chartFields}
          </Form>
        </Drawer>
      )}
    </div>
  );
}
